insert into public.profile (id, org_id, created_by, name, body, is_template) values
  ('61111111-0000-4000-8000-000000000011', null, null, 'Perceval', '{"subject":{"id":"perceval","role":"développeur backend","experienceYears":4},"available":["declared","vcsActivity","toolingContext","staticAnalysis"],"declared":{"stack":["TypeScript","NestJS","PostgreSQL"],"teamSize":6,"selfAssessedLevel":"advanced","notes":["# Ce que dit la personne de sa pratique\n\n> Réponses libres à un questionnaire interne. Non vérifiées.\n\n**Comment utilises-tu l''IA au quotidien ?**\n\nTout le temps, franchement je pourrais plus m''en passer. J''ai ChatGPT ouvert dans un onglet en permanence. Dès que je bloque sur un truc je lui demande, il me sort le bout de code et je l''adapte. Ça me fait gagner un temps fou sur le boilerplate, les regex, les requêtes SQL un peu velues.\n\n**Quel est ton niveau selon toi ?**\n\nPlutôt avancé. Je dirais que je suis dans le haut du panier de l''équipe là-dessus, les autres s''y sont mis bien après moi. J''ai fait plusieurs features complètes quasi entièrement générées.\n\n**Utilises-tu des fichiers de contexte, des règles, des instructions projet ?**\n\nPas vraiment, j''ai essayé un truc une fois mais j''ai pas trouvé ça très utile. Je préfère lui redonner le contexte à chaque fois dans le prompt, comme ça je maîtrise ce qu''il voit. Je copie les fichiers concernés directement dans la conversation.\n\n**Comment tu t''y prends pour une feature un peu grosse ?**\n\nJe découpe en petits morceaux et je fais générer chaque morceau. Après je recolle. Souvent faut reprendre pas mal parce qu''il perd le fil entre deux morceaux, ou il réinvente des trucs qui existent déjà dans le projet. Sur une grosse feature je peux passer une bonne partie du temps à corriger ce qu''il a sorti.\n\n**Et les tests ?**\n\nJe lui demande de générer les tests aussi quand j''ai le temps. Après honnêtement quand ça urge je les écris pas, ou je les fais passer vite fait.\n\n**Un truc qui te frustre ?**\n\nQu''il invente des méthodes qui existent pas. Et qu''il oublie ce qu''on s''est dit trois messages avant."]},"vcsActivity":{"pullRequests":{"total":63,"sizeDistribution":{"xs":18,"s":34,"m":10,"l":1,"xl":0},"medianFilesChanged":2,"medianLinesChanged":43,"medianCorrectionCommitsAfterOpen":4,"mergedWithoutHumanEditRatio":0.047619047619047616,"revertedRatio":0.07936507936507936,"medianReviewComments":7},"commits":{"aiCoauthoredRatio":0.04,"messageConventionCompliance":0.91,"medianPerPr":8},"tests":{"coverageStart":0.44,"coverageEnd":0.41,"prsWithTestsRatio":0.29},"parallelism":{"maxConcurrentBranches":2,"medianConcurrentBranches":1},"ci":{"failureRate":0.34,"medianRunsToGreen":3}},"staticAnalysis":{"ncloc":23124,"coverage":37,"complexity":592,"cognitiveComplexity":838,"codeSmells":641,"bugs":212,"duplicatedLinesDensity":18.4,"sqaleIndex":8358},"toolingContext":{"projectMemoryPresent":false,"rulesCount":0,"skillsCount":0,"agentsCount":0,"hooksCount":0,"declaredAssistantTools":["chatgpt-web"],"editorIntegration":false,"sessionsPerWeek":22,"tokensPerWeek":140000}}'::jsonb, true),
  ('61111111-0000-4000-8000-000000000012', null, null, 'Bohort', '{"subject":{"id":"bohort","role":"développeuse fullstack","experienceYears":7},"available":["declared","vcsActivity","toolingContext","staticAnalysis","workSession"],"declared":{"stack":["TypeScript","Next.js","Prisma"],"teamSize":4,"selfAssessedLevel":"intermediate","notes":["# Ce que dit la personne de sa pratique\n\n> Réponses libres à un questionnaire interne. Non vérifiées.\n\n**Comment utilises-tu l''IA au quotidien ?**\n\nJ''ai un assistant intégré à l''éditeur, et un fichier d''instructions à la racine du projet que je maintiens. Je commence rarement une feature sans lui avoir donné le contexte : les conventions, les fichiers concernés, ce qu''il ne doit pas toucher. Ça a changé beaucoup de choses par rapport à l''époque où je copiais-collais dans un chat.\n\n**Quel est ton niveau selon toi ?**\n\nDifficile à dire. Je sais que je fais mieux qu''il y a six mois, mais je vois aussi tout ce que je ne fais pas encore. Je dirais milieu de tableau.\n\n**Utilises-tu des fichiers de contexte, des règles, des instructions projet ?**\n\nOui, un `AGENTS.md` à la racine et quelques règles dans un dossier dédié. Je les mets à jour quand je vois l''assistant se tromper deux fois sur la même chose. C''est devenu un réflexe : si je corrige la même erreur deux fois, c''est que le contexte est incomplet, pas que le modèle est bête.\n\n**Comment tu t''y prends pour une feature un peu grosse ?**\n\nJ''écris d''abord ce que je veux, en clair, avec les cas limites. Ensuite je laisse générer une première passe complète. Puis je relis en entier et je reprends la main sur ce qui touche au métier, parce que c''est là qu''il se plante le plus. Les parties techniques standard, je les garde presque telles quelles.\n\n**Et les tests ?**\n\nSystématiques sur ce qui compte. Je fais générer les tests en même temps que le code, et je vérifie qu''ils échouent bien avant de les valider. Un test généré qui passe du premier coup, je m''en méfie.\n\n**Un truc qui te frustre ?**\n\nLe moment où je dois choisir entre corriger ce qu''il a fait et tout refaire moi-même. Je coupe trop tard, en général."]},"vcsActivity":{"rawPullRequests":[{"changedFiles":6,"additions":132,"deletions":43,"commits":7,"reviewComments":6},{"changedFiles":3,"additions":45,"deletions":25,"commits":7,"reviewComments":4},{"changedFiles":4,"additions":72,"deletions":39,"commits":10,"reviewComments":4},{"changedFiles":1,"additions":3,"deletions":3,"commits":5,"reviewComments":3},{"changedFiles":10,"additions":252,"deletions":137,"commits":10,"reviewComments":2},{"changedFiles":37,"additions":807,"deletions":440,"commits":10,"reviewComments":3},{"changedFiles":3,"additions":81,"deletions":33,"commits":7,"reviewComments":6},{"changedFiles":102,"additions":1941,"deletions":1230,"commits":13,"reviewComments":4},{"changedFiles":10,"additions":244,"deletions":144,"commits":8,"reviewComments":0},{"changedFiles":39,"additions":602,"deletions":458,"commits":4,"reviewComments":1},{"changedFiles":6,"additions":184,"deletions":40,"commits":3,"reviewComments":6},{"changedFiles":8,"additions":217,"deletions":57,"commits":8,"reviewComments":3}],"pullRequests":{"total":48,"sizeDistribution":{"xs":4,"s":12,"m":24,"l":7,"xl":1},"medianFilesChanged":7,"medianLinesChanged":251.5,"medianCorrectionCommitsAfterOpen":2,"mergedWithoutHumanEditRatio":0.20833333333333334,"revertedRatio":0.020833333333333332,"medianReviewComments":3},"commits":{"aiCoauthoredRatio":0.58,"messageConventionCompliance":0.88,"medianPerPr":7},"tests":{"coverageStart":0.47,"coverageEnd":0.68,"prsWithTestsRatio":0.71},"parallelism":{"maxConcurrentBranches":3,"medianConcurrentBranches":1},"ci":{"failureRate":0.12,"medianRunsToGreen":2}},"staticAnalysis":{"ncloc":36162,"coverage":61,"complexity":880,"cognitiveComplexity":915,"codeSmells":64,"bugs":0,"duplicatedLinesDensity":5.8,"sqaleIndex":1092},"toolingContext":{"projectMemoryPresent":true,"projectMemoryLastUpdated":"2026-07-12","rulesCount":0,"skillsCount":0,"agentsCount":0,"hooksCount":0,"declaredAssistantTools":["claude-code","chatgpt-web"],"editorIntegration":true,"sessionsPerWeek":31,"tokensPerWeek":1900000},"workSession":{"promptToCommitSteps":6,"humanInterventionsMidTask":2,"framingOnly":false,"rawText":"# Session\n\n**Personne**\n\nOn ajoute la relance de facture impayée. Contexte : `api/billing/`, conventions dans AGENTS.md. Trois règles métier :\n1. relance à J+7, J+15, J+30 après échéance\n2. on ne relance jamais un client dont le compte est suspendu\n3. une relance manuelle par un admin remet le compteur à zéro\n\nCommence par les tests, dans le style de `invoice-dunning.spec.ts` s''il existe déjà quelque chose de proche. Ne touche pas au module de paiement.\n\n**Assistant**\n\nIl n''existe pas de `invoice-dunning.spec.ts`. Le fichier le plus proche est `invoice-reminder.spec.ts`, qui teste un mécanisme de rappel avant échéance. Je m''aligne sur son style.\n\nQuestion avant d''écrire : la règle 3 remet à zéro le compteur, mais est-ce que la relance manuelle compte elle-même comme une relance dans la séquence, ou est-ce qu''elle est hors séquence ?\n\n**Personne**\n\nBonne question. Hors séquence. Elle remet à zéro et ne compte pas.\n\n**Assistant**\n\nCompris. J''écris les tests couvrant : les trois échéances, le client suspendu à chaque échéance, la remise à zéro par action admin, et le cas limite d''une suspension survenant entre deux relances.\n\n[9 tests écrits, tous en échec]\n\n**Personne**\n\nLe cas de la suspension entre deux relances, tu l''as traité comment ? Montre-moi juste ce test.\n\n**Assistant**\n\n[extrait du test]\n\n**Personne**\n\nNon. Si le compte est suspendu puis réactivé, on ne rattrape pas les relances manquées, on reprend à la prochaine échéance. Corrige ce test, puis passe à l''implémentation.\n\n**Assistant**\n\nCorrigé. J''implémente.\n\n[implémentation, 8 tests sur 9 passent]\n\n**Assistant**\n\nLe test de remise à zéro échoue. La cause : `DunningService` lit la date de dernière relance depuis `invoice.lastReminderAt`, qui est aussi écrit par le rappel avant échéance. Les deux mécanismes partagent le champ. Deux options : ajouter un champ dédié, ou distinguer par type dans une table d''historique.\n\n**Personne**\n\nChamp dédié, on ne va pas ouvrir une table pour ça. Mais préviens-moi si tu vois d''autres endroits qui lisent `lastReminderAt`.\n\n**Assistant**\n\nTrois autres endroits le lisent, dont un export comptable. Le champ dédié ne les casse pas, mais l''export ne verra jamais les relances d''impayé. À confirmer avec le métier.\n\n**Personne**\n\nNoté, je pose la question. Continue avec le champ dédié et laisse un TODO sur l''export."}}'::jsonb, true),
  ('61111111-0000-4000-8000-000000000013', null, null, 'Léodagan', '{"subject":{"id":"leodagan","role":"tech lead","experienceYears":11},"available":["declared","vcsActivity","toolingContext","staticAnalysis"],"declared":{"stack":["Go","TypeScript","React","Kubernetes"],"teamSize":8,"selfAssessedLevel":"advanced","notes":["# Ce que dit la personne de sa pratique\n\n> Réponses libres à un questionnaire interne. Non vérifiées.\n\n**Comment utilises-tu l''IA au quotidien ?**\n\nC''est devenu la façon par défaut de travailler. Je ne code presque plus à la main, sauf sur les parties où je sais que le contexte est trop implicite pour être transmis. Le travail s''est déplacé : je passe beaucoup plus de temps à cadrer et à relire qu''à écrire.\n\n**Quel est ton niveau selon toi ?**\n\nJe livre des grosses features de bout en bout sans reprendre la main en cours de route. En parallèle, non : un fil à la fois. L''équipe tourne à huit, et si je lance trois chantiers je ne relis plus rien correctement.\n\n**Utilises-tu des fichiers de contexte, des règles, des instructions projet ?**\n\nOui, et c''est le gros du travail. Instructions à la racine, règles par domaine, et quelques procédures réutilisables pour les tâches qui reviennent, genre l''ajout d''un endpoint ou la migration d''un schéma. Je considère que c''est du code : ça se relit, ça se refactorise, ça se supprime quand ça ne sert plus.\n\n**Comment tu t''y prends pour une feature un peu grosse ?**\n\nJe pars d''une spécification écrite avec les cas limites et les critères d''acceptation. Je fais valider la compréhension avant que la moindre ligne soit écrite : je demande de reformuler ce qui va être fait, et je corrige à ce stade. C''est là que ça se joue. Ensuite le code arrive en une passe, les tests avec, et je relis en diff. Si je dois corriger plus de deux fois la même chose, je remonte le problème dans les règles plutôt que dans le code.\n\n**Et les tests ?**\n\nÉcrits avant, systématiquement, et ils doivent échouer pour la bonne raison avant d''implémenter. Je vérifie ça explicitement.\n\n**Un truc qui te frustre ?**\n\nQue ça ne tienne pas encore tout seul sur plusieurs jours. Dès que le chantier dépasse une session, je dois reconstruire une partie du contexte. C''est la limite que je bute dessus en ce moment."]},"vcsActivity":{"rawPullRequests":[{"changedFiles":10,"additions":268,"deletions":216,"commits":5,"reviewComments":3},{"changedFiles":11,"additions":278,"deletions":127,"commits":6,"reviewComments":2},{"changedFiles":22,"additions":702,"deletions":219,"commits":6,"reviewComments":4},{"changedFiles":33,"additions":815,"deletions":344,"commits":7,"reviewComments":0},{"changedFiles":76,"additions":1702,"deletions":1319,"commits":11,"reviewComments":0},{"changedFiles":30,"additions":788,"deletions":304,"commits":7,"reviewComments":0},{"changedFiles":11,"additions":320,"deletions":174,"commits":6,"reviewComments":2},{"changedFiles":42,"additions":1319,"deletions":714,"commits":9,"reviewComments":1},{"changedFiles":3,"additions":91,"deletions":69,"commits":6,"reviewComments":2},{"changedFiles":6,"additions":163,"deletions":93,"commits":4,"reviewComments":4},{"changedFiles":6,"additions":166,"deletions":114,"commits":4,"reviewComments":3},{"changedFiles":29,"additions":1103,"deletions":383,"commits":10,"reviewComments":3}],"pullRequests":{"total":71,"sizeDistribution":{"xs":2,"s":8,"m":21,"l":32,"xl":8},"medianFilesChanged":13,"medianLinesChanged":579,"medianCorrectionCommitsAfterOpen":0,"mergedWithoutHumanEditRatio":0.5211267605633803,"revertedRatio":0,"medianReviewComments":2},"commits":{"aiCoauthoredRatio":0.87,"messageConventionCompliance":0.85,"medianPerPr":5},"tests":{"coverageStart":0.62,"coverageEnd":0.84,"prsWithTestsRatio":0.93},"parallelism":{"maxConcurrentBranches":2,"medianConcurrentBranches":1},"ci":{"failureRate":0.04,"medianRunsToGreen":1}},"staticAnalysis":{"ncloc":46032,"coverage":89,"complexity":1150,"cognitiveComplexity":1090,"codeSmells":7,"bugs":0,"duplicatedLinesDensity":1.7,"sqaleIndex":174},"toolingContext":{"projectMemoryPresent":true,"projectMemoryLastUpdated":"2026-07-11","rulesCount":3,"skillsCount":3,"agentsCount":2,"hooksCount":1,"declaredAssistantTools":["claude-code"],"editorIntegration":true,"sessionsPerWeek":26,"tokensPerWeek":6800000}}'::jsonb, true),
  ('61111111-0000-4000-8000-000000000014', null, null, 'Arthur', '{"subject":{"id":"arthur","role":"développeur indépendant","experienceYears":9},"available":["declared","vcsActivity","toolingContext","staticAnalysis","workSession"],"declared":{"stack":["Python","FastAPI","TypeScript","React","Terraform"],"teamSize":1,"notes":["La personne n''a pas répondu au questionnaire déclaratif."]},"vcsActivity":{"pullRequests":{"total":154,"sizeDistribution":{"xs":3,"s":9,"m":29,"l":65,"xl":48},"medianFilesChanged":29,"medianLinesChanged":1050,"medianCorrectionCommitsAfterOpen":1,"mergedWithoutHumanEditRatio":0.2987012987012987,"revertedRatio":0.01948051948051948,"medianReviewComments":1},"commits":{"aiCoauthoredRatio":0.91,"messageConventionCompliance":0.82,"medianPerPr":7},"tests":{"coverageStart":0.58,"coverageEnd":0.79,"prsWithTestsRatio":0.88},"parallelism":{"maxConcurrentBranches":7,"medianConcurrentBranches":4},"ci":{"failureRate":0.07,"medianRunsToGreen":2}},"staticAnalysis":{"ncloc":70224,"coverage":85,"complexity":1760,"cognitiveComplexity":1660,"codeSmells":10,"bugs":0,"duplicatedLinesDensity":2.4,"sqaleIndex":228},"toolingContext":{"projectMemoryPresent":true,"projectMemoryLastUpdated":"2026-07-14","rulesCount":0,"skillsCount":4,"agentsCount":2,"hooksCount":0,"declaredAssistantTools":["claude-code","codex"],"editorIntegration":true,"sessionsPerWeek":74,"tokensPerWeek":21000000},"workSession":{"promptToCommitSteps":3,"humanInterventionsMidTask":1,"framingOnly":false,"rawText":"# Session\n\n**Personne**\n\nFil 3. Migration du connecteur Stripe vers l''API v2. Spec dans `docs/specs/stripe-v2.md`, procédure de migration dans `.claude/skills/migrate-external-api/SKILL.md`. Applique la procédure, ne dévie pas. Tu me pings quand la phase 2 est verte.\n\n**Assistant**\n\nSpec et procédure lues. Quatre phases, chacune livrable et réversible seule : client v2 à côté du v1 et inutilisé, lectures sur v2 pendant que les écritures restent en v1, écritures sur v2, retrait du v1.\n\nInventaire : 34 appels répartis sur 6 fichiers, dont 4 dans `billing/` et 2 dans un script de reprise annuelle qui n''est pas couvert par les tests.\n\nLe script de reprise n''est pas dans le périmètre décrit par la spec. Je le migre aussi, je le laisse en v1, ou je m''arrête et tu tranches ?\n\n**Personne**\n\nLaisse en v1, ouvre un TODO avec la date de fin de support v1. Continue.\n\n**Assistant**\n\n[phases 1 et 2 exécutées]\n\nPhase 2 posée : les lectures passent par le client v2, les écritures restent en v1. `pytest tests/payments -q` au vert, 61 tests. La métrique de désaccord tourne depuis ce matin — la phase n''est pas verte tant qu''elle n''est pas plate à zéro pendant une semaine, c''est ce que dit la spec.\n\nUn point non prévu par la procédure : la v2 numérote les pages par curseur, la v1 par offset. Le job de relance nocturne pagine à la main sur l''offset, avec un `while` qui s''arrête quand la page revient vide. Sous curseur, la dernière page n''est jamais vide, elle est sans curseur suivant. Le job tournerait indéfiniment.\n\n**Personne**\n\nBien vu. Ne touche pas au job de relance dans ce fil, il est en cours de refonte sur le fil 1 et on va se marcher dessus. Note-le dans la spec comme dépendance croisée entre les deux fils, et arrête-toi là. Je te reprends après le merge du fil 1.\n\n**Assistant**\n\nNoté dans `docs/specs/stripe-v2.md`, section dépendances. Fil en pause, branche poussée, PR ouverte en brouillon avec la phase 3 non démarrée."}}'::jsonb, true)
